css:
.editorial-divided {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding-top: 1.25rem;
  border-top: 1px solid var(--border-subtle, rgba(0, 0, 0, 0.1));
  max-width: 68rem;
  margin-bottom: clamp(2rem, 4vw, 3rem);
}

.editorial-top-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.8125rem;
  color: var(--text-tertiary, #64748b);
  letter-spacing: 0.03em;
}

.editorial-section-id {
  font-weight: 600;
}

.editorial-timestamp {
  opacity: 0.85;
}

.editorial-section-title {
  font-size: clamp(1.75rem, 3.5vw, 2.75rem);
  line-height: 1.15;
  letter-spacing: -0.025em;
  font-weight: 600;
  color: var(--text-primary, #0f172a);
  margin: 0;
  text-wrap: balance;
}

.editorial-hairline {
  width: 100%;
  height: 1px;
  background-color: var(--border-subtle, rgba(0, 0, 0, 0.1));
  margin: 1rem 0;
  border: none;
}
